Translate("zhCN", "mulgore", {
	title = "莫高雷",
	aliases = { "莫高雷平原" },
	sections = {
		{
			title = "概述",
			text = [=[莫高雷是{link:tauren}牛头人{/link}的家园，一片{link:ginro-hearthkindle}金{/link}色草原与平缓丘陵交织的广阔土地，四面群山环绕。科多兽群在{link:burning-steppes}平原{/link}上吃草，清澈的水井和湖泊滋润着大地。高耸于这一切之上的，是牛头人的首都{link:thunder-bluff}雷霆崖{/link}的巨大台地，大酋长{link:cairne-bloodhoof}凯恩·血蹄{/link}的居所就在那里。对牛头人而言，这是{red:earth-mother}大地母亲{/red}的恩赐，是经历数百年流浪之后的一片和平之地。然而{link:quilboar}野猪人{/link}、{link:gnolls}豺狼人{/link}、{link:harpies}鹰身人{/link}和地精从四面八方步步紧逼，部族的年轻人必须在与它们的较量中证明自己。]=],
		},
		{
			title = "起源",
			text = [=[无数世代以来，{link:tauren}牛头人{/link}都是游牧民族，追随兽群穿越{link:kalimdor}卡利姆多{/link}的{link:burning-steppes}平原{/link}。{link:centaurs}半人马{/link}无情地猎杀他们，把他们赶出古老的土地，冲散了他们的部族。血蹄部族的{link:cairne-bloodhoof}凯恩{/link}立志召集族人，带领他们前往一片可以安居的土地。]=],
		},
		{
			title = "当今",
			text = [=[{link:centaurs}半人马{/link}被赶走了，但莫高雷并不安宁。{link:bristleback-quilboar}钢鬃野猪人{/link}与{link:red-cloud-mesa}红云台地{/link}的年轻{link:tauren}牛头人{/link}交战，并亵渎{link:red-rocks}赤色石{/link}的墓地。{link:palemane-gnolls}白鬃豺狼人{/link}把野生动物猎杀殆尽，对每一句和平的言语都报以刀刃。{link:windfury-harpies}狂风鹰身人{/link}在山脊上筑巢。{link:venture-company}风险投资公司{/link}的地精污染了神圣的水井，在东面的悬崖上挖了一座矿洞；{link:dwarves}矮人{/link}则在西面挖掘古老的秘密。如今，一队加拉克半人马再次出现在边界之内，一位被派去监视东方的{link:longwalkers}远行者{/link}没有回来。在西北方，{link:earthen-ring}大地之环{/link}的萨满祭司搭起了一座营地，一支陌生的民族从天而降：来自{link:windshapers}塑风者{/link}的{link:skyborne}天裔{/link}精灵，他们从{link:skywall}天空之墙{/link}降临，寻找新的盟友。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:tauren}牛头人{/link}。{/b}猎人、萨满祭司、德鲁伊和勇士住在{link:camp-narache}纳拉其营地{/link}、{link:bloodhoof-village}血蹄村{/link}和上方的城市中。{link:cairne-bloodhoof}凯恩{/link}之子{link:baine-bloodhoof}贝恩·血蹄{/link}酋长领导着村庄。
• {b}{link:earthen-ring}大地之环{/link}。{/b}来自数个民族的萨满祭司在{link:muln-earthfury}穆恩·地怒{/link}的带领下聚集于{link:camp-gev-rek}吉沃雷克营地{/link}。
• {b}{link:bristleback-quilboar}钢鬃野猪人{/link}。{/b}它们占据{link:brambleblade-ravine}刺刃峡谷{/link}，袭扰台地和{link:burning-steppes}平原{/link}。
• {b}{link:palemane-gnolls}白鬃豺狼人{/link}。{/b}它们盘踞在{link:palemane-rock}白鬃石{/link}，以及南部丘陵沿线的营地中。
• {b}{link:windfury-harpies}狂风鹰身人{/link}。{/b}它们栖息在东南方的山缘和{link:windfury-ridge}狂风山{/link}上。
• {b}{link:venture-company}风险投资公司{/link}。{/b}地精矿工、伐木工和监工，想把这片土地上的人赶得一干二净。]=],
		},
		{
			title = "历史",
			text = [=[• {b}长征。{/b}在无尽之海的岸边附近，年轻的酋长{link:thrall}萨尔{/link}遇上了正遭{link:centaurs}半人马{/link}袭击的{link:cairne-bloodhoof}凯恩{/link}族人。{link:orcs}兽人{/link}护送{link:tauren}牛头人{/link}的车队穿越{link:the-barrens}贫瘠之地{/link}来到莫高雷；作为回报，凯恩为萨尔指明了通往{link:stonetalon-mountains}石爪山{/link}先知的道路。
• {b}{link:third-war}第三次战争{/link}。{/b}凯恩让他的族人效忠{link:horde}部落{/link}，牛头人战士在{link:battle-of-mount-hyjal}海加尔山之战{/link}中与兽人并肩作战。
• {b}夺回莫高雷。{/b}在部落的帮助下，牛头人打破了半人马对{link:burning-steppes}平原{/link}的控制，让莫高雷成为所有部族永久的家园。他们在台地上建起了{link:thunder-bluff}雷霆崖{/link}。]=],
		},
		{
			title = "平原传说",
			text = [=[• 年轻的{link:tauren}牛头人{/link}要通过{link:rites-of-the-earthmother}大地母亲的仪式{/link}，才能在{link:thunder-bluff}雷霆崖{/link}赢得一席之地；这些仪式从{link:camp-narache}纳拉其营地{/link}一直通向大酋长的居所。
• 在台地上方的东南丘陵中，立着一座供奉太阳与月亮——安舍与穆沙——的神龛。牛头人尊崇这对双子，因为它们的光芒带来生命与指引，尽管它们并不像{link:elements}元素{/link}那样属于这个世界。
• 在石牛湖以西，一只被猎人们称为查库亚克的草原狼，在一片片树丛间潜行。]=],
		},
	},
})

Translate("zhCN", "red-cloud-mesa", {
