	sections = {
		{
			title = "概述",
			text = [=[红云台地是{link:mulgore}莫高雷{/link}南部的{link:razorfen-downs}高地{/link}，年轻的{link:tauren}牛头人{/link}在这里迈出成为猎人的第一步。{link:burning-steppes}平原{/link}陆行鸟和山狮在草地上游荡，长者们说，这里的人最引以为傲的就是敏锐的狩猎本领。营地东南有一口井，{link:chief-hawkwind}鹰风{/link}家族的{link:magatha-grimtotem}老祖母{/link}在那里打水。在南面的丘陵中，{link:seer-graytongue}灰舌先知{/link}守着他的居所；在东南远处的山坡上方，立着一座供奉安舍与穆沙的神龛。台地以东是{link:brambleblade-ravine}刺刃峡谷{/link}，{link:bristleback-quilboar}钢鬃野猪人{/link}趁夜从那里出来，伏击猎人，偷窃营地。]=],
		},
	},
})

Translate("zhCN", "camp-narache", {
	title = "纳拉其营地",
