	sections = {
		{
			title = "概述",
			text = [=[纳拉其营地是{link:red-cloud-mesa}红云台地{/link}上{link:chief-hawkwind}鹰风酋长{/link}的营地。这里满是帐篷、图腾和炊火，部族的年轻人就在这里开始{link:rites-of-the-earthmother}大地母亲的仪式{/link}。酋长教导说，部族的每个成员在万物的平衡中都有自己的位置，长者们连卑微的工作也会留意。他的儿子{link:grull-hawkwind}格鲁尔{/link}考验年轻的猎人。营地处在威胁之下，因为{link:bristleback-quilboar}钢鬃野猪人{/link}的督军已拟定了围攻营地的计划。在这里证明了自己的人，便沿着道路北上前往{link:bloodhoof-village}血蹄村{/link}。]=],
		},
	},
})

Translate("zhCN", "brambleblade-ravine", {
