			text = [=[刺刃峡谷切入{link:red-cloud-mesa}红云台地{/link}以东的丘陵。峡谷里荆棘丛生，{link:bristleback-quilboar}钢鬃野猪人{/link}在其中建起了一座简陋的村落。它们的袭击者从这里潜上台地，伏击{link:camp-narache}纳拉其营地{/link}的狩猎队。{link:quilboar}野猪人{/link}在峡谷中训练战斗野猪，教它们变得凶恶。它们的{link:chief-sharptusk-thornmantle}锋牙·刺鬃酋长{/link}把小屋建在峡谷的中心；纳拉其的{link:tauren}牛头人{/link}说，自从他们来到这片土地，他对他们发动的战争已夺去了许多性命。]=],
		},
	},
