			title = "概述",
			text = [=[血蹄村位于{link:mulgore}莫高雷{/link}的中心，在{link:red-cloud-mesa}红云台地{/link}和{link:thunder-bluff}雷霆崖{/link}之间的道路上。这是{link:cairne-bloodhoof}凯恩{/link}本人部族的村庄，由他的儿子{link:baine-bloodhoof}贝恩{/link}担任酋长。部族的导师们聚集在村中的大篝火旁：净化被污染的水井的萨满祭司{link:mull-thunderhorn}穆尔·雷角{/link}，精神领袖{link:zarlman-two-moons}扎尔曼·双月{/link}，战士{link:ruul-eagletalon}卢尔·鹰爪{/link}，以及猎人{link:harken-windtotem}哈肯·风之图腾{/link}和{link:skorn-whitecloud}斯考恩·白云{/link}。村里的旅店欢迎旅人。年轻的{link:tauren}牛头人{/link}从血蹄村出发，前往水井、矿洞和{link:gnolls}豺狼人{/link}营地；通过了幻象仪式的人，也从这里启程前往城市。]=],
		},
	},
})

Translate("zhCN", "water-wells-of-mulgore", {
	title = "莫高雷的水井",
	aliases = { "冰蹄水井", "雷角水井", "蛮鬃水井", "莫高雷水井" },
	sections = {
		{
			title = "概述",
			text = [=[三口神圣的水井滋润着{link:mulgore}莫高雷{/link}的{link:burning-steppes}平原{/link}，每一口都以一个{link:tauren}牛头人{/link}氏族命名。冰蹄水井在{link:bloodhoof-village}血蹄村{/link}东南，雷角水井在它以北，蛮鬃水井在{link:thunder-bluff}雷霆崖{/link}以北。这些水井给牛头人和他们赖以生存的兽群带来生命。{link:venture-company}风险投资公司{/link}的地精和他们的仆从把三口井全都弄脏了。为了净化它们，萨满祭司{link:mull-thunderhorn}穆尔·雷角{/link}用这片土地自身所提供的东西为每口井制作一个图腾，然后必须在井边举行仪式，而且往往是在地精守卫的眼皮底下。]=],
		},
	},
})

Translate("zhCN", "the-venture-co-mine", {
