			text = [=[狂风山是{link:mulgore}莫高雷{/link}北方高耸的边缘，{link:burning-steppes}平原{/link}在这里向群山攀升。这里是{link:windfury-harpies}狂风鹰身人{/link}的要塞。她们的女族长和女巫栖息在峭壁之间，她们的风巫呼唤着风。{link:tauren}牛头人{/link}把{link:harpies}鹰身人{/link}视为莫高雷的天敌之一，却也珍视北方鸟群的蔚蓝色和古铜色羽毛，用来制作觐见大酋长时佩戴的头饰。据说，鹰身人海特拉什统领着西北方的鸟群。]=],
