			title = "概述",
			text = [=[金色平原在{link:thunder-bluff}雷霆崖{/link}以东铺展开来，是城市与东面悬崖之间的一片高草之海。{link:burning-steppes}平原{/link}山狮在这里狩猎，据说老陆行鸟{link:mazzranache}马兹拉纳其{/link}也在同一片土地上游荡。一只名叫{link:ghost-howl}鬼嚎{/link}的巨大白狼不时穿过这片平原，它的皮毛上仍带着与恶魔作战留下的伤疤。{link:venture-company}风险投资公司{/link}的地精在他们的矿洞和水井之间开出道路，横穿草原。如今，平原上出现了他们的一台伐木机，{link:tauren}牛头人{/link}绝不容许这台机器砍倒{link:mulgore}莫高雷{/link}的哪怕一棵树。]=],
		},
	},
})

Translate("zhCN", "camp-gev-rek", {
