			text = [=[远行者是{link:tauren}牛头人{/link}最受信任的斥候。他们只听命于大酋长{link:cairne-bloodhoof}凯恩·血蹄{/link}一人，执行他最机密的差事。远行者可以从头带和饰有羽毛的法杖认出来。即使是{link:bloodhoof-village}血蹄村{/link}的酋长、凯恩的亲生儿子，也只能请求他们的帮助。]=],
